questionvariables.text:
/* 1. GÉNÉRATION ALÉATOIRE (A l'envers pour garantir de bonnes racines) */
a: rand([1, -1, 2, -2])$ /* On force deux racines distinctes, une négative et une positive pour l'exhaustivité */
x1: rand([-5, -4, -3, -2, -1])$ x2: rand([1, 2, 3, 4, 5])$ 
/* Calcul de b et c à partir de la forme factorisée a(x-x1)(x-x2) = ax^2 - a(x1+x2)x + a(x1*x2) */
b: -a*(x1 + x2)$ c: a*x1*x2$ 
/* 2. DÉFINITION DE L'INÉQUATION */
ineqs: [a*x^2 + b*x + c > 0, a*x^2 + b*x + c >= 0, a*x^2 + b*x + c < 0, a*x^2 + b*x + c <= 0]$ eq: rand(ineqs)$ op_ineq: op(eq)$ 
/* 3. CALCUL DE LA RÉPONSE CORRECTE */
/* Règle : a>0 -> positive à l'extérieur. a<0 -> positif à l'intérieur */
if a > 0 then (
    if op_ineq = ">" then ans_correct: x < x1 or x > x2,
    if op_ineq = ">=" then ans_correct: x <= x1 or x >= x2,
    if op_ineq = "<" then ans_correct: x1 < x and x < x2,
    if op_ineq = "<=" then ans_correct: x1 <= x and x <= x2
) else (
    if op_ineq = ">" then ans_correct: x1 < x and x < x2,
    if op_ineq = ">=" then ans_correct: x1 <= x and x <= x2,
    if op_ineq = "<" then ans_correct: x < x1 or x > x2,
    if op_ineq = "<=" then ans_correct: x <= x1 or x >= x2
)$ 
/* 4. ANTICIPATION DES ERREURS POUR LES FEEDBACKS CIBLÉS */

/* err_sign : l'élève inverse la règle du signe (prend l'intérieur au lieu de l'extérieur) */
if a > 0 then (
    if op_ineq = ">" then err_sign: x1 < x and x < x2,
    if op_ineq = ">=" then err_sign: x1 <= x and x <= x2,
    if op_ineq = "<" then err_sign: x < x1 or x > x2,
    if op_ineq = "<=" then err_sign: x <= x1 or x >= x2
) else (
    if op_ineq = ">" then err_sign: x < x1 or x > x2,
    if op_ineq = ">=" then err_sign: x <= x1 or x >= x2,
    if op_ineq = "<" then err_sign: x1 < x and x < x2,
    if op_ineq = "<=" then err_sign: x1 <= x and x <= x2
)$ 
/* err_val : l'élève a bon intérieur/extérieur, mais se trompe de racines (ex: erreur de signe sur c) */
c_err: -c$ delta_err: b^2 - 4*a*c_err$ x1_err: (-b - sqrt(delta_err))/(2*a)$ x2_err: (-b + sqrt(delta_err))/(2*a)$ /* Remise en ordre au cas où le tri serait inversé */
if x1_err > x2_err then (
    tmp: x1_err,
    x1_err: x2_err,
    x2_err: tmp
)$ 
if a > 0 then (
    if op_ineq = ">" then err_val: x < x1_err or x > x2_err,
    if op_ineq = ">=" then err_val: x <= x1_err or x >= x2_err,
    if op_ineq = "<" then err_val: x1_err < x and x < x2_err,
    if op_ineq = "<=" then err_val: x1_err <= x and x <= x2_err
) else (
    if op_ineq = ">" then err_val: x1_err < x and x < x2_err,
    if op_ineq = ">=" then err_val: x1_err <= x and x <= x2_err,
    if op_ineq = "<" then err_val: x < x1_err or x > x2_err,
    if op_ineq = "<=" then err_val: x <= x1_err or x >= x2_err
)$ 
/* 5. TEXTES POUR LA CORRECTION GÉNÉRALE */
delta: b^2 - 4*a*c$ signe_a_txt: if a > 0 then "positif" else "négatif"$ forme_txt: if a > 0 then "tournée vers le haut (\cup)" else "tournée vers le bas (\cap)"$ regle_txt: if a > 0 then "positif à l'extérieur des racines et négatif à l'intérieur" else "négatif à l'extérieur des racines et positif à l'intérieur"$
